// ============================================================
// Evidence Gate - نسخه مبتنی بر تأیید بازبین
// محتوای گزارش فقط از خروجی پژوهشگر اصلی گرفته می‌شود.
// ============================================================

function parseObject(value) {
  if (value && typeof value === 'object' && !Array.isArray(value)) {
    return value;
  }

  if (typeof value !== 'string') return {};

  try {
    const parsed = JSON.parse(
      value.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/i, '').trim()
    );

    return parsed && typeof parsed === 'object' && !Array.isArray(parsed)
      ? parsed
      : {};
  } catch {
    return {};
  }
}

function arr(value) {
  return Array.isArray(value) ? value : [];
}

function str(value) {
  return value == null ? '' : String(value).trim();
}

const decision = $input.first().json || {};

if (decision.route !== 'approved') {
  throw new Error(
    'گزارش بدون عبور از مسیر approved نباید وارد Evidence Gate شود.'
  );
}

const report = parseObject(decision.final_report);

if (!str(report.topic_title)) {
  throw new Error('گزارش نهایی پژوهشگر اصلی فاقد عنوان است.');
}

const sources = arr(report.main_sources);
const examples = arr(report.examples);
const interdisciplinary = arr(report.interdisciplinary);

const researchId = str(decision.research_id);

const isTechnicalTest =
  str(report.topic_title) === 'تست اتصال';

// ------------------------------------------------------------
// آماده‌سازی ردیف‌های شواهد برای Data Table فعلی
// ------------------------------------------------------------

const evidenceFlat = [];

for (const source of sources) {
  evidenceFlat.push({
    research_id: researchId,
    kind: 'source',
    title: str(source.name),
    author_year: str(source.author_year),
    source_type: str(source.source_type),
    tier: str(source.tier),
    evidence_strength: str(source.evidence_strength),

    note: [
      str(source.main_result),
      str(source.note)
    ].filter(Boolean).join(' | '),

    link: str(source.link)
  });
}

for (const example of examples) {
  evidenceFlat.push({
    research_id: researchId,
    kind: 'example',
    title: str(example.person_event),
    author_year: '',
    source_type: str(example.source_type),
    tier: '',
    evidence_strength: str(example.documentation_level),
    note: str(example.relevance),
    link: str(example.source)
  });
}

for (const item of interdisciplinary) {
  evidenceFlat.push({
    research_id: researchId,
    kind: 'interdisciplinary',
    title: str(item.domain),
    author_year: '',
    source_type: '',
    tier: '',
    evidence_strength: str(item.credibility),
    note: str(item.fact),
    link: str(item.source)
  });
}

// ------------------------------------------------------------
// خروجی
// فیلدهای علمی از گزارش پژوهشگر اصلی حفظ می‌شوند.
// ------------------------------------------------------------

return [{
  json: {
    ...report,

    chat_id: decision.chat_id,
    research_id: researchId,

    review_status: isTechnicalTest ? 'test' : 'pass',
    is_technical_test: isTechnicalTest,

    verified_source_count: Number(
      decision.verified_source_count ?? sources.length
    ),

    dropped_sources_count: 0,
    dropped_claims_count: 0,

    quality_warnings: arr(decision.quality_warnings),

    verification_notice: str(decision.verification_notice),

    evidence_flat: evidenceFlat
  }
}];

// ============================================================
// قالب‌بندی گزارش پژوهشگر اصلی + پیوست وضعیت بازبینی
// گزارش علمی در هر دو حالت از ایجنت اول گرفته می‌شود.
// در حالت fail گزارش حذف نمی‌شود؛ موارد تأییدنشده جداگانه مشخص می‌شوند.
// ============================================================

const d = $input.first().json || {};
const lines = [];

function str(value) {
  return value === null || value === undefined ? '' : String(value).trim();
}
function arr(value) { return Array.isArray(value) ? value : []; }
function obj(value) { return value && typeof value === 'object' && !Array.isArray(value) ? value : {}; }
function refsText(value) {
  const refs = arr(value).map(str).filter(Boolean);
  return refs.length ? ` [منابع: ${refs.join(', ')}]` : '';
}
function addTitle(title) { lines.push(''); lines.push(title); }
function addBullet(value) { if (str(value)) lines.push('• ' + str(value)); }
function addUrl(value) { if (str(value)) lines.push('   لینک: ' + str(value)); }
function pct(value) {
  if (value === null || value === undefined || value === '') return null;
  const n = Number(value);
  return Number.isFinite(n) && n >= 0 && n <= 100 ? Math.round(n) : null;
}

const isFail = str(d.review_status).toLowerCase() === 'fail';
const isTest = d.review_status === 'test' || d.is_technical_test === true;
const issues = arr(d.unapproved_topics);

function issueForPath(path) {
  return issues.find(item => str(item.claim_path) === path) || null;
}
function issueForSource(sourceId) {
  return issues.find(item => str(item.source_id).toUpperCase() === str(sourceId).toUpperCase()) || null;
}
function marker(issue) {
  if (!issue) return '';
  return ' ⚠️ [نیازمند بررسی]';
}
function shortText(value, max = 150) {
  const s = str(value).replace(/\s+/g, ' ');
  if (s.length <= max) return s;
  return s.slice(0, max - 1).trimEnd() + '…';
}
function showIssueDetails(item, index) {
  const confidence = pct(item.confidence_percent);
  const title = str(item.topic) || str(item.claim_path) || 'مورد نیازمند بررسی';
  const status = str(item.status) || 'تأیید نهایی نشده';
  const confText = confidence === null ? 'اطمینان: اعلام نشده' : `اطمینان بازبین: ${confidence}%`;
  lines.push(`${index + 1}. ${shortText(title, 90)} | ${status} | ${confText}`);
  if (str(item.reason)) lines.push('   ' + shortText(item.reason, 150));
}

lines.push('📌 گزارش تحقیق: ' + (str(d.topic_title) || '-'));

if (isTest) {
  lines.push('');
  lines.push('✅ اتصال برقرار است');
  lines.push('این پیام صرفاً نتیجه تست فنی است و شامل تحقیق علمی نیست.');
} else {
  if (isFail) {
    lines.push('');
    lines.push('⚠️ بازبینی: پس از یک دور اصلاح، بعضی بخش‌ها همچنان نیازمند بررسی‌اند.');
    lines.push('ابتدا گزارش کامل پژوهش را می‌بینی؛ نمای کوتاه اعتبارسنجی در انتهای پیام آمده است. بخش‌های علامت‌گذاری‌شده تأیید نهایی نشده‌اند.');
  }

  // ----------------------------------------------------------
  // جمع‌بندی
  // ----------------------------------------------------------
  const summary = obj(d.executive_summary);
  if (str(summary.text)) {
    addTitle('🧭 جمع‌بندی کلی' + (issueForPath('executive_summary') ? ' ⚠️' : ''));
    lines.push(str(summary.text) + refsText(summary.source_ids) + marker(issueForPath('executive_summary')));
  }

  // ----------------------------------------------------------
  // تعاریف و مفاهیم
  // ----------------------------------------------------------
  const definitions = arr(d.scope_and_definitions);
  if (definitions.length) {
    addTitle('📖 تعاریف و مفاهیم پایه');
    definitions.forEach((item, index) => {
      const issue = issueForPath(`scope_and_definitions[${index}]`);
      lines.push('• ' + str(item.term) + ': ' + str(item.definition) + refsText(item.source_ids) + marker(issue));
      if (str(item.importance)) lines.push('   اهمیت: ' + str(item.importance));
    });
  }

  // ----------------------------------------------------------
  // چارچوب نظری
  // ----------------------------------------------------------
  const theories = arr(d.theoretical_framework);
  if (theories.length) {
    addTitle('🧠 چارچوب نظری');
    theories.forEach((item, index) => {
      const issue = issueForPath(`theoretical_framework[${index}]`);
      lines.push('• ' + str(item.concept) + ': ' + str(item.explanation) + refsText(item.source_ids) + marker(issue));
      if (str(item.relevance)) lines.push('   ارتباط با سؤال: ' + str(item.relevance));
    });
  }

  // ----------------------------------------------------------
  // یافته‌های اصلی
  // ----------------------------------------------------------
  const findings = arr(d.key_findings);
  if (findings.length) {
    addTitle('🔑 یافته‌های اصلی');
    findings.forEach((item, index) => {
      const issue = issueForPath(`key_findings[${index}]`);
      lines.push(`${index + 1}. ${str(item.finding)}` + refsText(item.source_ids) + marker(issue));
      if (str(item.explanation)) lines.push('   توضیح: ' + str(item.explanation));
      if (str(item.evidence_strength)) lines.push('   قدرت شواهد گزارش‌شده: ' + str(item.evidence_strength));
      if (str(item.limitations)) lines.push('   محدودیت: ' + str(item.limitations));
      lines.push('');
    });
  } else {
    addTitle('🔑 یافته‌های اصلی');
    lines.push('پژوهشگر اصلی در این گزارش یافته اصلی ثبت نکرده است.');
  }

  // ----------------------------------------------------------
  // نگاشت به دوره
  // ----------------------------------------------------------
  const mapping = obj(d.course_mapping);
  if (str(mapping.module) || str(mapping.lesson) || str(mapping.angle)) {
    addTitle('🎯 کاربرد در دوره');
    lines.push('بخش: ' + (str(mapping.module) || 'مشخص نشده'));
    lines.push('درس: ' + (str(mapping.lesson) || 'مشخص نشده'));
    lines.push('زیر‌بخش: ' + (str(mapping.section) || 'مشخص نشده'));
    if (str(mapping.angle)) lines.push('زاویه آموزشی: ' + str(mapping.angle));
  }

  // ----------------------------------------------------------
  // منابع اصلی
  // ----------------------------------------------------------
  const sources = arr(d.main_sources);
  addTitle('📚 منابع اصلیِ درج‌شده در گزارش پژوهشگر');
  if (!sources.length) {
    lines.push('پژوهشگر اصلی منبعی در فهرست main_sources ارائه نکرده است.');
  } else {
    sources.forEach((source, index) => {
      const issue = issueForSource(source.source_id);
      lines.push(`${index + 1}. ${str(source.name) || 'عنوان درج نشده'}${str(source.source_id) ? ' [' + str(source.source_id) + ']' : ''}` + marker(issue));
      if (str(source.author_year)) lines.push('   نویسنده/سال: ' + str(source.author_year));
      if (str(source.source_type)) lines.push('   نوع منبع: ' + str(source.source_type));
      if (str(source.tier)) lines.push('   طبقه منبع گزارش‌شده: ' + str(source.tier));
      if (str(source.study_type)) lines.push('   نوع پژوهش: ' + str(source.study_type));
      if (str(source.population_context)) lines.push('   جامعه/زمینه: ' + str(source.population_context));
      if (str(source.method_summary)) lines.push('   روش: ' + str(source.method_summary));
      if (str(source.main_result)) lines.push('   نتیجه گزارش‌شده: ' + str(source.main_result));
      if (str(source.limitations)) lines.push('   محدودیت‌ها: ' + str(source.limitations));
      addUrl(source.link);
      lines.push('');
    });
  }

  // ----------------------------------------------------------
  // بازبینی روش‌شناسی
  // ----------------------------------------------------------
  const evidenceReviews = arr(d.evidence_review);
  if (evidenceReviews.length) {
    addTitle('🔬 ارزیابی روش‌شناختی');
    evidenceReviews.forEach((item, index) => {
      const issue = issueForPath(`evidence_review[${index}]`);
      lines.push('منبع: ' + str(item.source_id) + marker(issue));
      if (str(item.methodological_assessment)) lines.push('   ارزیابی: ' + str(item.methodological_assessment));
      if (str(item.strengths)) lines.push('   نقاط قوت: ' + str(item.strengths));
      if (str(item.limitations)) lines.push('   محدودیت‌ها: ' + str(item.limitations));
      if (str(item.relevance)) lines.push('   ارتباط: ' + str(item.relevance));
    });
  }

  // ----------------------------------------------------------
  // اختلاف‌ها
  // ----------------------------------------------------------
  const contradictions = arr(d.contradictions);
  if (contradictions.length) {
    addTitle('⚖️ اختلاف نتایج و تبیین‌ها');
    contradictions.forEach((item, index) => {
      const issue = issueForPath(`contradictions[${index}]`);
      lines.push('• ' + str(item.claim_or_issue) + refsText(item.source_ids) + marker(issue));
      if (str(item.description)) lines.push('   شرح: ' + str(item.description));
      if (str(item.interpretation)) lines.push('   تفسیر محتاطانه: ' + str(item.interpretation));
    });
  }

  // ----------------------------------------------------------
  // مثال‌ها
  // ----------------------------------------------------------
  const examples = arr(d.examples);
  if (examples.length) {
    addTitle('🧩 مثال‌های مستندِ درج‌شده');
    examples.forEach((item, index) => {
      const issue = issueForPath(`examples[${index}]`);
      lines.push('• ' + str(item.person_event) + marker(issue));
      if (str(item.description)) lines.push('   شرح: ' + str(item.description));
      if (str(item.relevance)) lines.push('   ارتباط: ' + str(item.relevance));
      if (str(item.documentation_level)) lines.push('   سطح مستندسازی گزارش‌شده: ' + str(item.documentation_level));
      addUrl(item.source);
    });
  }

  // ----------------------------------------------------------
  // یافته‌های بین‌رشته‌ای
  // ----------------------------------------------------------
  const interdisciplinary = arr(d.interdisciplinary);
  if (interdisciplinary.length) {
    addTitle('🌐 یافته‌های بین‌رشته‌ای');
    interdisciplinary.forEach((item, index) => {
      const issue = issueForPath(`interdisciplinary[${index}]`);
      lines.push('• [' + str(item.domain) + '] ' + str(item.fact) + marker(issue));
      if (str(item.relevance)) lines.push('   ارتباط: ' + str(item.relevance));
      if (str(item.limitation)) lines.push('   محدودیت: ' + str(item.limitation));
      addUrl(item.source);
    });
  }

  // ----------------------------------------------------------
  // شکاف‌های پژوهشی
  // ----------------------------------------------------------
  const gaps = arr(d.research_gaps);
  if (gaps.length) {
    addTitle('🔎 شکاف‌های پژوهشی');
    gaps.forEach((item, index) => {
      const issue = issueForPath(`research_gaps[${index}]`);
      lines.push('• ' + str(item.gap) + refsText(item.source_ids) + marker(issue));
      if (str(item.why_it_matters)) lines.push('   اهمیت: ' + str(item.why_it_matters));
    });
  }

  // ----------------------------------------------------------
  // واژه‌نامه
  // ----------------------------------------------------------
  const glossary = arr(d.glossary);
  if (glossary.length) {
    addTitle('📘 واژه‌نامه');
    glossary.forEach((item, index) => {
      const issue = issueForPath(`glossary[${index}]`);
      lines.push('• ' + str(item.term) + ': ' + str(item.definition) + refsText(item.source_ids) + marker(issue));
    });
  }

  // ----------------------------------------------------------
  // پیشنهادهای محتوا
  // ----------------------------------------------------------
  const suggestions = arr(d.content_suggestions);
  if (suggestions.length) {
    addTitle('✅ پیشنهادهای تولید محتوا');
    suggestions.forEach((item, index) => {
      const issue = issueForPath(`content_suggestions[${index}]`);
      lines.push('• ' + str(item.title) + refsText(item.scientific_basis_source_ids) + marker(issue));
      if (str(item.format)) lines.push('   قالب: ' + str(item.format));
      if (str(item.idea)) lines.push('   ایده: ' + str(item.idea));
      if (str(item.caution)) lines.push('   احتیاط: ' + str(item.caution));
      lines.push('');
    });
  }

  const limitations = arr(d.research_limitations);
  if (limitations.length) {
    addTitle('⚠️ محدودیت‌های تحقیقِ گزارش‌شده');
    limitations.forEach(addBullet);
  }

  // ----------------------------------------------------------
  // پیوست بازبینی: پس از نمایش گزارش کامل
  // ----------------------------------------------------------
  if (isFail) {
    addTitle('🧾 اعتبارسنجی در یک نگاه');
    lines.push('این بخش فقط چشم‌انداز کوتاهی از بازبینی است؛ متن پژوهش بالا گزارش کامل پژوهشگر اصلی است.');
    if (issues.length) {
      const MAX_VISIBLE_ISSUES = 5;
      issues.slice(0, MAX_VISIBLE_ISSUES).forEach(showIssueDetails);
      if (issues.length > MAX_VISIBLE_ISSUES) {
        lines.push(`و ${issues.length - MAX_VISIBLE_ISSUES} مورد دیگر که در این نمای کوتاه فهرست نشده‌اند.`);
      }
    } else {
      lines.push('بازبین گزارش را تأیید نکرد، اما مورد مشخصی برای نمایش در فهرست بازخورد ثبت نشده است.');
    }
    const overall = pct(d.overall_confidence_percent);
    lines.push('اطمینان کلی بازبین به ارزیابی خود: ' + (overall === null ? 'اعلام نشده' : overall + '%'));
    lines.push('این درصد، خودارزیابی مدل از اطمینانش به ممیزی است؛ نه احتمال آماری نادرست بودن ادعا.');
    lines.push('گزارش پژوهش حفظ شده است؛ موارد علامت‌خورده را پیش از استناد قطعی دستی بررسی کن.');
  } else {
    addTitle('🛡️ وضعیت کنترل کیفیت');
    lines.push('وضعیت بازبینی: ' + (str(d.review_status) || 'نامشخص'));
    lines.push('منابع تأییدشده: ' + Number(d.verified_source_count || 0));
    if (str(d.verification_notice)) lines.push(str(d.verification_notice));
    arr(d.quality_warnings).map(str).filter(Boolean).forEach(w => lines.push('• ' + w));
  }
}

// تقسیم متن به قطعه‌های پیام با حفظ مرز خطوط
const fullText = lines.join('\n').trim();
const CHUNK = 3500;
const chunks = [];
let current = '';
for (const line of fullText.split('\n')) {
  const candidate = current ? current + '\n' + line : line;
  if (candidate.length <= CHUNK) {
    current = candidate;
    continue;
  }
  if (current) chunks.push(current);
  current = '';
  if (line.length > CHUNK) {
    for (let i = 0; i < line.length; i += CHUNK) chunks.push(line.slice(i, i + CHUNK));
  } else {
    current = line;
  }
}
if (current) chunks.push(current);
if (!chunks.length) chunks.push('نتیجه‌ای برای نمایش وجود ندارد.');

return chunks.map((chunk, index) => ({
  json: { chunk, idx: index, chat_id: d.chat_id }
}));

const input = $input.first().json || {};

const isRetry = input.route === 'revise';

const revisionRound = Number(input.revision_round ?? 0);

const output = {
  chat_id: input.chat_id,
  research_id: input.research_id,

  brief: input.brief || {},
  course_outline: input.course_outline || '',

  revision_round: revisionRound,
  is_revision: isRetry || Boolean(input.is_revision),

  previous_report: input.previous_report || null,
  review_feedback: input.review_feedback || null
};

if (
  !output.brief ||
  typeof output.brief !== 'object' ||
  Array.isArray(output.brief)
) {
  throw new Error('brief برای شروع تحقیق معتبر نیست.');
}

if (!output.course_outline) {
  throw new Error('سرفصل‌های دوره در ورودی موجود نیست.');
}

return [{ json: output }];

function parseObject(value) {
  if (value && typeof value === 'object' && !Array.isArray(value)) {
    return value;
  }

  if (typeof value !== 'string') return {};

  try {
    const parsed = JSON.parse(
      value
        .replace(/^```(?:json)?\s*/i, '')
        .replace(/\s*```$/i, '')
        .trim()
    );

    return parsed && typeof parsed === 'object' && !Array.isArray(parsed)
      ? parsed
      : {};
  } catch (error) {
    return {};
  }
}

function getResearchInput() {
  try {
    return $('Researcher Input').item.json;
  } catch (error) {
    try {
      return $('Researcher Input').last().json;
    } catch (fallbackError) {
      throw new Error('ورودی متناظر پژوهشگر اصلی پیدا نشد.');
    }
  }
}

const agentOutput = $input.first().json || {};
const report = parseObject(agentOutput.output ?? agentOutput);
const state = getResearchInput();

if (!report.topic_title) {
  throw new Error('گزارش پژوهشگر اصلی فاقد topic_title است.');
}

if (!Array.isArray(report.main_sources)) {
  throw new Error('ساختار main_sources گزارش معتبر نیست.');
}

return [{
  json: {
    report,

    chat_id: state.chat_id,
    research_id: state.research_id,

    brief: state.brief,
    course_outline: state.course_outline,

    revision_round: Number(state.revision_round ?? 0),
    is_revision: Boolean(state.is_revision)
  }
}];

