parameters.jsCode:
// ============================================================
// تصمیم بازبینی - حداکثر یک دور اصلاح
// route = approved | revise | failed
// در صورت رد دور دوم، فهرست موارد تأییدنشده همراه درصد اطمینان بازبین
// برگردانده می‌شود؛ درصدها برآورد خود بازبین هستند، نه احتمال آماری کالیبره‌شده.
// ============================================================

function obj(value) {
  if (value && typeof value === 'object' && !Array.isArray(value)) return value;
  if (typeof value !== 'string') return {};
  try {
    const parsed = JSON.parse(value.replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/i, '').trim());
    return parsed && typeof parsed === 'object' && !Array.isArray(parsed) ? parsed : {};
  } catch { return {}; }
}
function arr(value) { return Array.isArray(value) ? value : []; }
function str(value) { return value == null ? '' : String(value).trim(); }
function id(value) { return str(value).toUpperCase(); }
function pct(value) {
  if (value === null || value === undefined || value === '') return null;
  const n = Number(value);
  if (!Number.isFinite(n) || n < 0 || n > 100) return null;
  return Math.round(n);
}
function urlKey(value) {
  try { const u = new URL(str(value)); u.hash = ''; return u.toString().replace(/\/+$/, ''); }
  catch { return ''; }
}
function getPackage() {
  try { return $('Package Report for Review').item.json; }
  catch {
    try { return $('Package Report for Review').last().json; }
    catch { throw new Error('بسته متناظر با گزارش و دور بازبینی پیدا نشد.'); }
  }
}
function resolveTopic(report, path) {
  if (path === 'executive_summary') return str(obj(report.executive_summary).text) || 'جمع‌بندی کلی';
  const match = /^([a-z_]+)\[(\d+)\]$/.exec(str(path));
  if (!match) return str(path) || 'موضوع نامشخص';
  const section = match[1];
  const index = Number(match[2]);
  const item = arr(report[section])[index] || {};
  const titleBySection = {
    scope_and_definitions: item.term || item.definition,
    theoretical_framework: item.concept || item.explanation,
    key_findings: item.finding || item.explanation,
    evidence_review: item.source_id ? `ارزیابی منبع ${item.source_id}` : item.methodological_assessment,
    contradictions: item.claim_or_issue || item.description,
    examples: item.person_event || item.description,
    interdisciplinary: item.domain || item.fact,
    research_gaps: item.gap,
    glossary: item.term || item.definition,
    content_suggestions: item.title
  };
  return str(titleBySection[section]) || `${section}[${index}]`;
}
const input = $input.first().json || {};
const review = obj(input.output ?? input);
const pack = getPackage();
const report = obj(pack.report);
const round = Number(pack.revision_round ?? 0);
const MAX_REVISIONS = 1; // فقط یک بار پژوهشگر برای اصلاح فراخوانی می‌شود.

const sources = arr(report.main_sources);
const sourceChecks = arr(review.source_checks);
const claimChecks = arr(review.claim_checks);
const rejectedSources = arr(review.rejected_sources);
const unsupportedClaims = arr(review.unsupported_claims);
const sourceIds = sources.map(s => id(s.source_id));
const sourceSet = new Set(sourceIds);
const uniqueIds = sourceIds.length === sourceSet.size;

const sourceMap = new Map();
for (const check of sourceChecks) {
  const sid = id(check.source_id);
  if (sid && !sourceMap.has(sid)) sourceMap.set(sid, check);
}
const claimMap = new Map();
for (const check of claimChecks) {
  const path = str(check.claim_path);
  if (path && !claimMap.has(path)) claimMap.set(path, check);
}

const allSourcesVerified = sources.length > 0 && uniqueIds &&
  sourceChecks.length === sources.length &&
  sources.every(source => {
    const check = sourceMap.get(id(source.source_id));
    return Boolean(check) && str(check.status).toLowerCase() === 'verified' &&
      str(check.matched_title).length >= 5 && str(check.page_evidence).length >= 20;
  });

const expected = [];
function addCited(path, refs) {
  expected.push({path, refs: arr(refs).map(id).filter(Boolean), url: '', urlBased: false});
}
function addURL(path, url) {
  expected.push({path, refs: [], url: urlKey(url), urlBased: true});
}
const summary = obj(report.executive_summary);
if (str(summary.text)) addCited('executive_summary', summary.source_ids);
for (const [section, refsKey] of [
  ['scope_and_definitions','source_ids'],['theoretical_framework','source_ids'],
  ['key_findings','source_ids'],['contradictions','source_ids'],
  ['research_gaps','source_ids'],['glossary','source_ids'],
  ['content_suggestions','scientific_basis_source_ids']
]) {
  arr(report[section]).forEach((item, i) => addCited(`${section}[${i}]`, item[refsKey]));
}
arr(report.evidence_review).forEach((item, i) => addCited(`evidence_review[${i}]`, [item.source_id]));
arr(report.examples).forEach((item, i) => addURL(`examples[${i}]`, item.source));
arr(report.interdisciplinary).forEach((item, i) => addURL(`interdisciplinary[${i}]`, item.source));

function claimPass(claim) {
  const check = claimMap.get(claim.path);
  if (!check || str(check.status).toLowerCase() !== 'supported') return false;
  if (claim.urlBased) {
    const checkedUrls = arr(check.source_urls_checked).map(urlKey).filter(Boolean);
    return Boolean(claim.url) && checkedUrls.includes(claim.url) && str(check.page_evidence).length >= 20;
  }
  if (claim.refs.length === 0) return false;
  if (!claim.refs.every(sid => sourceSet.has(sid))) return false;
  const checkedRefs = arr(check.source_ids_checked).map(id);
  return claim.refs.every(sid => checkedRefs.includes(sid));
}
const allExpectedClaimsChecked = expected.every(c => claimMap.has(c.path));
const allClaimsSupported = expected.every(claimPass);

const noScientificContent =
  arr(report.scope_and_definitions).length === 0 && arr(report.theoretical_framework).length === 0 &&
  arr(report.key_findings).length === 0 && arr(report.evidence_review).length === 0 &&
  arr(report.contradictions).length === 0 && arr(report.examples).length === 0 &&
  arr(report.interdisciplinary).length === 0 && arr(report.research_gaps).length === 0 &&
  arr(report.glossary).length === 0 && arr(report.content_suggestions).length === 0;
const explicitNoEvidence = /(شواهد معتبر|منابع معتبر|رفرنس معتبر).{0,100}(پیدا نشد|یافت نشد|کافی نیست|قابل تأیید نیست|قابل اتکا نیست)|(پیدا نشد|یافت نشد|کافی نیست).{0,100}(شواهد|منابع|رفرنس)/i.test(str(summary.text));
const honestNoEvidence = sources.length === 0 && noScientificContent && explicitNoEvidence;

if (str(report.topic_title) === 'تست اتصال') {
  return [{json:{route:'approved',final_report:report,chat_id:pack.chat_id,research_id:pack.research_id,
    revision_round:round,verified_source_count:0,quality_warnings:[],
    verification_notice:'این خروجی صرفاً تست فنی است و ادعای علمی نیست.'}}];
}

const reviewerAccepts = str(review.decision).toLowerCase() === 'accept' &&
  str(review.review_status).toLowerCase() === 'pass';
const noExplicitRejections = rejectedSources.length === 0 && unsupportedClaims.length === 0;
const approved = (honestNoEvidence && reviewerAccepts && sourceChecks.length === 0 && noExplicitRejections) ||
  (reviewerAccepts && allSourcesVerified && allExpectedClaimsChecked && allClaimsSupported && noExplicitRejections);

if (approved) {
  return [{json:{route:'approved',final_report:report,chat_id:pack.chat_id,research_id:pack.research_id,
    brief:pack.brief,course_outline:pack.course_outline,revision_round:round,
    verified_source_count:sources.length,quality_warnings:[],
    verification_notice:'محتوای گزارش عیناً از خروجی پژوهشگر اصلی گرفته شده است؛ بازبین فقط درباره انتشار تصمیم‌گیری کرده است.'}}];
}

const feedback = {
  review_status: review.review_status || 'نامشخص', decision: review.decision || 'revise',
  overall_confidence_percent: pct(review.overall_confidence_percent),
  source_checks: sourceChecks, rejected_sources: rejectedSources,
  claim_checks: claimChecks, unsupported_claims: unsupportedClaims,
  revision_instructions: arr(review.revision_instructions), review_notes: arr(review.review_notes),
  gate_checks: {all_sources_verified:allSourcesVerified,all_expected_claims_checked:allExpectedClaimsChecked,
    all_claims_supported:allClaimsSupported,unique_source_ids:uniqueIds}
};

// اگر هنوز دور اصلاح مصرف نشده، دقیقاً یک بار به پژوهشگر اصلی برگرد.
if (round < MAX_REVISIONS) {
  return [{json:{route:'revise',chat_id:pack.chat_id,research_id:pack.research_id,
    brief:pack.brief,course_outline:pack.course_outline,revision_round:round+1,is_revision:true,
    previous_report:report,review_feedback:feedback,topic_title:report.topic_title}}];
}

// ------------------------------------------------------------
// دور دوم بازبینی هم تأیید نکرد: فهرست موضوعات تأییدنشده بساز.
// confidence_percent یعنی اطمینان بازبین به ارزیابیِ عدم تأیید، نه احتمال غلط بودن ادعا.
// ------------------------------------------------------------
const issues = new Map();
function addIssue(key, issue) {
  const safeKey = str(key) || `issue_${issues.size+1}`;
  const existing = issues.get(safeKey);
  if (!existing) {
    issues.set(safeKey, issue);
  } else {
    if ((!existing.reason || existing.reason.length < str(issue.reason).length) && issue.reason) existing.reason = issue.reason;
    if (issue.confidence_percent != null) existing.confidence_percent = issue.confidence_percent;
    if (issue.confidence_note) existing.confidence_note = issue.confidence_note;
    if (issue.status) existing.status = issue.status;
    if (issue.recommendation) existing.recommendation = issue.recommendation;
  }
}

for (const source of sources) {
  const sid = id(source.source_id);
  const check = sourceMap.get(sid);
  const explicitlyRejected = rejectedSources.find(r => id(r.source_id) === sid);
  const sourceVerified = Boolean(check) &&
    str(check.status).toLowerCase() === 'verified' &&
    str(check.matched_title).length >= 5 &&
    str(check.page_evidence).length >= 20 &&
    !explicitlyRejected;

  if (!sourceVerified) {
    const reason = str(explicitlyRejected?.reason || check?.reason) ||
      'منبع در خروجی بازبینی مستقل به‌طور کامل تأیید نشد.';
    const conf = pct(explicitlyRejected?.confidence_percent ?? check?.confidence_percent);
    addIssue(`source:${sid}`, {
      type:'source', topic:str(source.name) || `منبع ${sid || 'بدون شناسه'}`,
      claim_path:'', source_id:sid || '', status:str(check?.status || 'not_reviewed'),
      reason, confidence_percent: conf,
      confidence_note: conf == null ? 'بازبین درصد اطمینان معتبری برای این مورد ارائه نکرد؛ درصدی حدس زده نشده است.' : '',
      recommendation:str(explicitlyRejected?.required_action) || 'مشخصات و صفحه رسمی منبع را دوباره بررسی کن.'
    });
  }
}

if (!uniqueIds) {
  addIssue('source_id_integrity', {
    type:'source', topic:'یکتایی شناسه‌های منابع', claim_path:'', source_id:'',
    status:'metadata_mismatch',
    reason:'در فهرست منابع شناسه تکراری وجود دارد؛ بنابراین ارجاع‌ها به‌صورت یکتا قابل ردیابی نیستند.',
    confidence_percent:100,
    confidence_note:'این درصد به اطمینان از مشاهده شناسه‌های تکراری در ساختار گزارش اشاره دارد، نه درباره محتوای علمی.',
    recommendation:'برای هر منبع شناسه یکتا تعیین کن و تمام source_ids وابسته را مطابق آن اصلاح کن.'
  });
}

const unsupportedMap = new Map();
for (const item of unsupportedClaims) {
  const path = str(item.claim_path);
  if (path && !unsupportedMap.has(path)) unsupportedMap.set(path,item);
}

for (const claim of expected) {
  const check = claimMap.get(claim.path);
  const supported = claimPass(claim);
  if (!supported) {
    const explicit = unsupportedMap.get(claim.path);
    const reviewerStatus = str(check?.status).toLowerCase();
    const structuralFailure = Boolean(check) && reviewerStatus === 'supported';
    let reason = structuralFailure ? '' : str(explicit?.reason || check?.reason);
    if (structuralFailure) {
      if (!claim.urlBased && claim.refs.length === 0) {
        reason = 'بازبین ادعا را پشتیبانی‌شده اعلام کرده، اما این بخش هیچ ارجاعی به منبع ندارد؛ از نظر ساختاری قابل تأیید نیست.';
      } else {
        reason = 'بازبین ادعا را پشتیبانی‌شده اعلام کرده، اما ارجاعات یا شواهد قابل ردیابی آن با الزامات کنترل نهایی سازگار نیستند.';
      }
    }
    if (!reason) {
      if (!check) reason = 'بازبین برای این بخش نتیجه بررسی ثبت نکرده است؛ بنابراین تأیید آن قابل اثبات نیست.';
      else if (!claim.urlBased && claim.refs.length === 0) reason = 'این بخش ارجاع به منبع تأییدشده ندارد.';
      else reason = 'شواهد بررسی‌شده برای تأیید کامل این بخش کافی نیست.';
    }
    const status = str(explicit?.status || check?.status || 'not_verifiable');
    const conf = structuralFailure ? 100 : pct(explicit?.confidence_percent ?? check?.confidence_percent);
    addIssue(`claim:${claim.path}`, {
      type:'topic', topic:resolveTopic(report, claim.path),
      claim_path:claim.path, source_id:'', status, reason,
      confidence_percent: structuralFailure ? 100 : conf,
      confidence_note: structuralFailure
        ? '۱۰۰٪ اطمینان به این است که کنترل ساختاری ارجاعات در این اجرا شکست خورده؛ نه احتمال نادرستی علمی ادعا.'
        : (conf == null ? 'بازبین درصد اطمینان معتبری ارائه نکرد؛ درصدی حدس زده نشده است.' : ''),
      recommendation:str(explicit?.required_action) || 'ادعا را اصلاح یا محدود کن و برای آن شواهد معتبر و مستقیم ارائه بده.'
    });
  }
}

// مواردی که بازبین صریحاً در unsupported_claims آورده است، حتی اگر ساختار موردانتظار کامل نبوده باشد.
for (const item of unsupportedClaims) {
  const path = str(item.claim_path);
  if (!path) continue;
  addIssue(`claim:${path}`, {
    type:'topic', topic:resolveTopic(report,path), claim_path:path, source_id:'',
    status:str(item.status || 'not_verifiable'), reason:str(item.reason || 'پشتیبانی کافی تأیید نشده است.'),
    confidence_percent:pct(item.confidence_percent),
    confidence_note:pct(item.confidence_percent) == null ? 'بازبین درصد اطمینان معتبری ارائه نکرد؛ درصدی حدس زده نشده است.' : '',
    recommendation:str(item.required_action) || 'شواهد را تکمیل یا ادعا را محدود کن.'
  });
}

let unapprovedTopics = [...issues.values()];
if (unapprovedTopics.length === 0) {
  const notes = arr(review.review_notes).map(str).filter(Boolean);
  const overall = pct(review.overall_confidence_percent);
  unapprovedTopics.push({
    type:'report', topic:'پذیرش کلی گزارش', claim_path:'', source_id:'',
    status:str(review.review_status || 'partial'),
    reason:notes.join(' | ') || 'بازبین در دور دوم گزارش را تأیید نکرد؛ اما دلیل هر مورد به‌صورت جداگانه در خروجی مشخص نشده است.',
    confidence_percent:overall,
    confidence_note:overall == null ? 'بازبین درصد اطمینان کلی معتبری ارائه نکرد.' : '',
    recommendation:'خروجی بازبین و موارد بازبینی‌نشده را دستی بررسی کن.'
  });
}

unapprovedTopics = unapprovedTopics.map(item => ({
  ...item,
  confidence_percent:pct(item.confidence_percent)
}));

return [{json:{route:'failed',chat_id:pack.chat_id,research_id:pack.research_id,
  topic_title:report.topic_title,revision_round:round,
  final_report:report,
  unapproved_topics:unapprovedTopics,
  overall_confidence_percent:pct(review.overall_confidence_percent),
  quality_warnings:[
    'یک دور اصلاح انجام شد، اما گزارش پس از بازبینی دوم به‌طور کامل تأیید نشد.',
    'گزارش زیر آخرین خروجی پژوهشگر اصلی است و نباید همه بخش‌های آن تأییدشده تلقی شوند.',
    'درصدها برآورد بازبین از اطمینان به ارزیابیِ عدم تأیید هستند؛ نه احتمال آماریِ نادرست بودن ادعا.'
  ],
  verification_notice:'آخرین گزارش پژوهشگر اصلی همراه با فهرست مواردی که پس از یک بار اصلاح تأیید نشدند، ارائه می‌شود.'
}}];

const d = $input.first().json || {};

const report = d.final_report && typeof d.final_report === 'object' && !Array.isArray(d.final_report)
  ? d.final_report
  : {};

return [{
  json: {
    // Preserve all research fields from the last output of the first agent.
    ...report,

    chat_id: d.chat_id,
    research_id: d.research_id,
    topic_title: d.topic_title || report.topic_title || 'تحقیق',

    // These fields control presentation only; they do not replace the report.
    review_status: 'fail',
    is_technical_test: false,

    // Count sources in the report separately from verified sources.
    reported_source_count: Array.isArray(report.main_sources) ? report.main_sources.length : 0,
    verified_source_count: 0,
    dropped_sources_count: 0,
    dropped_claims_count: 0,

    unapproved_topics: Array.isArray(d.unapproved_topics)
      ? d.unapproved_topics
      : [],

    overall_confidence_percent: d.overall_confidence_percent ?? null,

    quality_warnings: Array.isArray(d.quality_warnings)
      ? d.quality_warnings
      : ['پس از یک دور اصلاح، بعضی منابع یا ادعاها تأیید نهایی نشدند.'],

    verification_notice:
      d.verification_notice ||
      'گزارش پژوهشگر اصلی به همراه موارد تأییدنشده در ادامه آمده است.'
  }
}];
